import React, { useMemo } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, CartesianGrid } from "recharts";

// A new, self-contained Plan class
class Plan {
  constructor(goals, disposableIncome, currentSavings) {
    this.goals = goals || [];
    this.disposableIncome = disposableIncome || 0;
    this.currentSavings = currentSavings || 0;
    this.monthlyAllocations = {};
    this.totalAllocations = {};
    this.totalSavingsNeeded = 0;
    this.totalMonthlyNeeded = 0;
    this.calculate();
  }

  calculate() {
    const sortedGoals = [...this.goals].sort((a, b) => (a.priority || 0) - (b.priority || 0));
    let remainingIncome = this.disposableIncome;

    this.totalSavingsNeeded = this.goals.reduce((sum, goal) => sum + (goal.amount || 0), 0);

    const currentSavingsNeeded = Math.max(0, this.totalSavingsNeeded - this.currentSavings);
    const totalGoalMonths = this.goals.reduce((sum, goal) => sum + (goal.months || 0), 0);

    if (totalGoalMonths > 0) {
      this.totalMonthlyNeeded = currentSavingsNeeded / totalGoalMonths;
    } else {
      // If there are no months specified, the entire amount is needed immediately.
      this.totalMonthlyNeeded = currentSavingsNeeded;
    }

    // The allocation logic for the bar chart.
    // This calculates how much of the disposable income can be allocated to each goal per month.
    sortedGoals.forEach(goal => {
        const remainingAmount = (goal.amount || 0) - (goal.saved || 0);
        const idealMonthlyForGoal = remainingAmount > 0 ? (remainingAmount / (goal.months || 1)) : 0;
        const allocation = Math.min(remainingIncome, idealMonthlyForGoal);

        if (goal && goal.id) {
          this.monthlyAllocations[goal.id] = allocation;
          this.totalAllocations[goal.id] = allocation * (goal.months || 1);
        }
        remainingIncome -= allocation;
    });
  }
}

export default function Overview({ goals = [], income = { monthlyDisposableIncome: 0 }, currentSavings = 0 }) {
  const plan = useMemo(() => new Plan(goals, income.monthlyDisposableIncome, currentSavings), [goals, income, currentSavings]);

  const monthlySavingsData = useMemo(() => {
    return plan.goals.map(goal => ({
      name: goal.name,
      'Target Amount': goal.amount || 0,
      'Monthly Allocation': plan.monthlyAllocations[goal.id] || 0,
    }));
  }, [plan]);

  const totalTargetAmount = plan.totalSavingsNeeded;
  const shortfall = Math.max(0, plan.totalMonthlyNeeded - plan.disposableIncome);
  const totalSaved = plan.currentSavings;
  const currentSavingsNeeded = Math.max(0, totalTargetAmount - totalSaved);

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-4 rounded-lg shadow-lg border border-gray-200">
          <p className="font-semibold">{label}</p>
          {payload.map((entry, index) => (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: ${entry.value.toLocaleString()}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  if (!goals.length) {
    return (
      <div className="p-6">
        <div className="text-center text-gray-500">
          No goals found. Add some goals to see your savings plan.
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="bg-white rounded-lg shadow p-6">
        <h2 className="text-lg font-semibold mb-4">Monthly Savings Allocation</h2>
        <div className="h-96">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={monthlySavingsData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis 
                dataKey="name" 
                angle={-45} 
                textAnchor="end" 
                height={100}
                interval={0}
              />
              <YAxis />
              <Tooltip content={<CustomTooltip />} />
              <Legend />
              <Bar dataKey="Target Amount" fill="#60a5fa" radius={[4, 4, 0, 0]} />
              <Bar dataKey="Monthly Allocation" fill="#4ade80" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mt-6">
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Current Savings Needed</h3>
          <p className="text-2xl font-semibold mt-2">${currentSavingsNeeded.toLocaleString()}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Monthly Savings Needed</h3>
          <p className="text-2xl font-semibold mt-2">${(plan.totalMonthlyNeeded || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Monthly Shortfall</h3>
          <p className="text-2xl font-semibold mt-2 text-red-500">${shortfall.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
        </div>
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-sm font-medium text-gray-500">Total Saved</h3>
          <p className="text-2xl font-semibold mt-2">${totalSaved.toLocaleString()}</p>
        </div>
      </div>
    </div>
  );
}
